package edu.pe.cibertec.saibm.libro.infrastructure.out.persistence;
import java.util.UUID; import jakarta.persistence.*; import edu.pe.cibertec.saibm.libro.domain.model.Book;
@Entity @Table(name="books") public class BookJpaEntity { @Id UUID id; @Column(nullable=false,length=255) String title; @Column(nullable=false,columnDefinition="text") String description; @Column(nullable=false,length=255) String author; @Column(name="image_url",nullable=false,length=300) String imageUrl; @Column(nullable=false) boolean active; protected BookJpaEntity(){} private BookJpaEntity(Book b){apply(b);} static BookJpaEntity from(Book b){return new BookJpaEntity(b);} void apply(Book b){id=b.id();title=b.title();description=b.description();author=b.author();imageUrl=b.imageUrl();active=b.active();} Book domain(){return new Book(id,title,description,author,imageUrl,active);} }
